import { describe, it, expect } from "vitest";
import * as path from "node:path";
import * as fs from "node:fs";
import * as os from "node:os";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { claudeConverter } from "../src/converters/claude.js";
import { opencodeConverter } from "../src/converters/opencode.js";
import type { HarnessConfig, PermissionAction } from "../src/schema.js";

// Mirrors features/permission-fidelity.feature and features/conversion-reporting.feature,
// generated by openspec-bdd from openspec/changes/conversion-matrix/specs/.

const HERE = path.dirname(fileURLToPath(import.meta.url));
const _OPENCODE_PROJECT = path.join(HERE, "fixtures", "opencode-project");

function tmpDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), "harnessport-perm-"));
}

function emptyConfig(): HarnessConfig {
  return {
    rules: [], agents: [], skills: [], commands: [],
    mcpServers: [], permissions: [], hooks: [], formatters: [], items: [],
  };
}

function _withPermission(
  tool: string,
  pattern: string,
  action: PermissionAction,
): HarnessConfig {
  return { ...emptyConfig(), permissions: [{ tool, pattern, action }] };
}

function withFormatter(glob: string, command: string): HarnessConfig {
  return { ...emptyConfig(), formatters: [{ glob, command }] };
}

function writeOpenCodePermissions(dir: string, permission: unknown): void {
  fs.writeFileSync(
    path.join(dir, "opencode.json"),
    JSON.stringify({ $schema: "https://opencode.ai/config.json", permission }, null, 2),
  );
  fs.writeFileSync(path.join(dir, "AGENTS.md"), "# Rules\n");
}

describe("Requirement: A permission tool name converts in a form the target matches", () => {
  it("An OpenCode ask rule reaches Claude Code in matchable form", () => {
    const src = tmpDir();
    writeOpenCodePermissions(src, { bash: { "git push *": "ask" } });

    const out = tmpDir();
    claudeConverter.export(out, opencodeConverter.import(src), {});
    const settings = fs.readFileSync(
      path.join(out, ".claude", "settings.local.json"),
      "utf-8",
    );
    expect(settings).toContain("Bash(git push *)");
    expect(settings).not.toContain("bash(git push *)");
  });

});

describe("Requirement: The Claude formatter reads the edited file path from stdin", () => {

  it("The runner passes the stdin path to the formatter and skips other globs", () => {
    const dir = tmpDir();
    claudeConverter.export(dir, withFormatter("*.ts", "node record.mjs"), {});
    fs.writeFileSync(
      path.join(dir, "record.mjs"),
      'import { writeFileSync } from "node:fs";writeFileSync("recorded.txt", process.argv.at(-1));',
    );
    const run = (file: string) =>
      spawnSync("node", [".claude/hooks/harnessport-format.mjs", "*.ts", "node", "record.mjs"], {
        cwd: dir,
        input: JSON.stringify({ tool_input: { file_path: file } }),
      }).status;
    expect(run("/tmp/x/a.py")).toBe(0);
    expect(fs.existsSync(path.join(dir, "recorded.txt"))).toBe(false);
    expect(run("/tmp/x/a.ts")).toBe(0);
    expect(fs.readFileSync(path.join(dir, "recorded.txt"), "utf-8")).toBe("/tmp/x/a.ts");
  });

  it("A formatter with shell syntax is dropped and writes no runner", () => {
    const dir = tmpDir();
    const result = claudeConverter.export(dir, withFormatter("*.py", "ruff format && ruff check"), {});
    expect(result.items.find((i) => i.kind === "formatter")?.status).toBe("dropped");
    expect(fs.existsSync(path.join(dir, ".claude/hooks/harnessport-format.mjs"))).toBe(false);
  });
});
